export const SCENES=[{"id": "eclipse", "name": "黒蝕竜・月下の機関都市", "enemy": "黒蝕竜", "place": "月下の機関都市"}, {"id": "bridge", "name": "雷獣・崩落する天空橋", "enemy": "雷獣", "place": "崩落する天空橋"}, {"id": "furnace", "name": "炎王・灼熱の炉心", "enemy": "炎王", "place": "灼熱の炉心"}, {"id": "cathedral", "name": "鏡騎士・水晶聖堂", "enemy": "鏡騎士", "place": "水晶聖堂"}, {"id": "harbor", "name": "深海竜・沈みゆく港", "enemy": "深海竜", "place": "沈みゆく港"}, {"id": "forest", "name": "影蜘蛛・月光の森", "enemy": "影蜘蛛", "place": "月光の森"}, {"id": "train", "name": "装甲鷲・疾走する列車", "enemy": "装甲鷲", "place": "疾走する列車"}, {"id": "desert", "name": "砂時計の巨人・遺跡", "enemy": "砂時計の巨人", "place": "遺跡"}, {"id": "snow", "name": "氷の女王・白夜の砦", "enemy": "氷の女王", "place": "白夜の砦"}, {"id": "moon", "name": "虚無王・月の祭壇", "enemy": "虚無王", "place": "月の祭壇"}];
export const PATTERNS=[{id:'victory',name:'正面突破',win:true},{id:'defeat',name:'攻撃失敗',win:false},{id:'feint',name:'好機からの敗北',win:false},{id:'awakening',name:'劣勢から覚醒',win:true},{id:'revival',name:'敗北後の復活',win:true}];
export const imagePath=(scene,pattern)=>`/battles/${scene}-${pattern}.png`;
export function chooseReach(win,rng){const options=PATTERNS.filter(p=>p.win===win);return options[Math.min(options.length-1,Math.floor(rng()*options.length))].id;}
